package com.pavithran.aichat; import com.google.gson.annotations.SerializedName; import retrofit2.*; import retrofit2.converter.gson.GsonConverterFactory; import retrofit2.http.Body; import retrofit2.http.POST; import java.util.UUID; public final class Api { private Api(){} public record ChatRequest(@SerializedName("conversationId") UUID conversationId,@SerializedName("deviceId") String deviceId,@SerializedName("message") String message){} public record ChatResponse(@SerializedName("conversationId") UUID conversationId,@SerializedName("reply") String reply){} public interface Service{@POST("api/chat") Call<ChatResponse> chat(@Body ChatRequest request);} public static final Service service=new Retrofit.Builder().baseUrl(BuildConfig.API_BASE_URL).addConverterFactory(GsonConverterFactory.create()).build().create(Service.class); }
